package com.yeyamo_mobile.api.payment_service.infrastructure.web;
import static com.yeyamo_mobile.api.payment_service.application.AdminPaymentDtos.*;import java.time.Instant;import java.util.*;import org.springframework.data.domain.*;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.payment_service.application.AdminPaymentService;import com.yeyamo_mobile.api.payment_service.domain.PaymentStatus;
@RestController@RequestMapping("/api/v1/payments/admin")public class AdminPaymentController{private final AdminPaymentService service;public AdminPaymentController(AdminPaymentService s){service=s;}@GetMapping@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN','SUPPORT')")public Page<AdminPaymentSummary>list(@RequestParam(required=false)String search,@RequestParam(required=false)PaymentStatus status,@RequestParam(required=false)String provider,@RequestParam(required=false)String currency,@RequestParam(required=false)String userId,@RequestParam(required=false)String partnerId,@RequestParam(required=false)UUID bookingId,@RequestParam(required=false)String providerPaymentId,@RequestParam(required=false)String idempotencyKey,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant createdFrom,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant createdTo,Pageable pageable){return service.list(search,status,provider,currency,userId,partnerId,bookingId,providerPaymentId,idempotencyKey,createdFrom,createdTo,pageable);}@GetMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN','SUPPORT')")public AdminPaymentDetail detail(@PathVariable UUID id){return service.detail(id);}@GetMapping("/anomalies")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')")public List<PaymentAnomaly>anomalies(){return service.anomalies();}@PostMapping("/reconciliation")@PreAuthorize("hasRole('SUPER_ADMIN')")public ReconciliationResponse reconciliation(Authentication auth,@RequestHeader(value="X-Correlation-Id",required=false)String correlation){return service.reconcile(auth.getName(),correlation);}}
